STOP = {"a", "an", "and", "the", "is", "it", "to", "of", "in", "by", "be", "so", "then", "with", "you", "your", "yourself"}


def words(text):
    result = []
    for raw in text.split():
        word = raw.strip(string.punctuation).lower()
        if word:
            result.append(word)
    return result


def frequencies(text):
    counts = {}
    for word in words(text):
        counts[word] = counts.get(word, 0) + 1
    return counts


def top_words(text, n, skip=()):
    counts = {w: c for w, c in frequencies(text).items() if w not in skip}
